*{box-sizing:border-box}body{margin:0;color:#0c1c2a;font-family:Arial,sans-serif}.nav{background:#071a2c;color:#fff;padding:22px}.nav div{width:min(900px,92%);margin:auto;display:flex;justify-content:space-between}.nav a{color:#fff;text-decoration:none}.article{width:min(820px,92%);margin:65px auto}.tag{color:#176bff;font-weight:bold}.article h1{font-size:clamp(35px,6vw,62px);line-height:1.08;margin:18px 0}.lead{font-size:20px;color:#60707f;line-height:1.6}.cover{width:100%;max-height:470px;object-fit:cover;border-radius:16px;margin:25px 0}.content{font-size:18px;line-height:1.85}.content p{margin:0 0 1.3em}.back{display:inline-block;margin-top:30px;color:#176bff;font-weight:bold;text-decoration:none}</style></head><body><header class="nav"><div><strong>LINKSmart TECHNOLOGY</strong><a href="/blog.php">Retour au blog</a></div></header><article class="article"><div class="tag"><?=e($post['author_name'])?> · <?=e(date('d/m/Y',strtotime($post['published_at'])))?></div><h1><?=e($post['title'])?></h1><p class="lead"><?=e($post['excerpt'])?></p><?php if($post['cover_image']):?><img class="cover" src="<?=e($post['cover_image'])?>" alt=""><?php endif;?><div class="content"><?php foreach(preg_split('/\R{2,}/',trim($post['content']))?:[] as $paragraph):?><p><?=nl2br(e($paragraph))?></p><?php endforeach;?></div><a class="back" href="/blog.php">← Tous les articles</a></article></body></html>
